std::mutex mtx;
int shared = 0;
std::atomic<int> counter{0};

void worker() {
    {
        std::lock_guard<std::mutex> lk(mtx);
        ++shared;
    }
    counter.fetch_add(1, std::memory_order_relaxed);
}

int main() {
    std::thread t1(worker), t2(worker);
    t1.join(); t2.join();
}

