#include <type_traits>

template <typename T>
void serialize(std::ostream& os, const T& v) {
    if constexpr (std::is_pointer_v<T>) {
        if (v) serialize(os, *v);     // 指针：解引用后递归
    } else if constexpr (std::is_arithmetic_v<T>) {
        os << v;
    } else {
        v.serialize(os);               // 自定义类型
    }
}

